/**
 * Sisera Flees
 * ------------
 * Sisera abandons his chariot and flees on foot toward the tent of Jael, wife of Heber the Kenite. Stage: a lone figure staggering across a sodden field, mud and armour, a tent by the great tree in the distance; fading storm light, a lone tent lamp.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: chariot
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./deborah-kit.js.
 */

import { THREE, createScene, tent, oak, wheat, rain, chariot, person, birds } from './deborah-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 2952260161, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents */
    tent(W, group, -3.0, 0, -14.3, 1.23, 0xc8b088, W.r() * 6);
    tent(W, group, 9.5, 0, -21.0, 1.11, 0xd8c8a0, W.r() * 6);
    tent(W, group, 10.5, 0, -23.7, 0.91, 0xa8704a, W.r() * 6);
    tent(W, group, -20.1, 0, -11.8, 1.04, 0x8a6a44, W.r() * 6);

    /* trees: broadleaf shade */
    oak(W, group, -65.9, 0, -14.5, 1.08, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 51.2, 0, -53.8, 1.16, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -59.9, 0, -6.3, 1.08, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0xeeca84, head: 0xffe696 });

    /* storm: rain sheets across the whole frame */
    rain(W, group, 900, 230, 65, 16);

    /* chariot: gold-trimmed cab and spoked wheels */
    chariot(W, group, -0.5, 0, -3.2, 1.1, { ry: -0.55, gold: 0x826e48 });

    /* hero: the chariot */
    chariot(W, group, 0, 0, 0, 1.25, { ry: 0.3, gold: 0x826e48 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, ry: 0.19, s: 1.02 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
